import {WAVE_SECONDS} from './campaign.mjs';
import {Run} from './model.mjs';
import {Condenser} from './condenser.mjs';
import {RECIPES} from './catalog.mjs';
import {ACCESSORIES,updateAccessories,updateAccessoryZones,updateAccessoryProjectiles,triggerWaterChain,MUZZLES} from './equipment.mjs';
import {visibleInCombat} from './view.mjs';
import {weaponName,afterEvolutionShot,evolutionHit,acidSwarm,updateEvolutions} from './evolutions.mjs';
// Only these fields belong to an individual weapon. Combat world and character are shared.
const fields=['attachments','muzzle','shot','angle','condenser','accessoryCharge','waterChainReady','waterParticles','waterImpacts','waterEmissionCarry','waterStreamId','waterNextId','waterEmitting','waterMuzzle','waterLastAngle','magneticTime','evolutionShots','targetId'];
const fresh=gun=>({gun,attachments:[],muzzle:null,shot:0,angle:0,condenser:new Condenser(),accessoryCharge:{},waterChainReady:0,waterParticles:[],waterImpacts:[],waterEmissionCarry:0,waterStreamId:0,waterNextId:1,waterEmitting:false,waterMuzzle:null,waterLastAngle:0,magneticTime:0,evolutionShots:0,targetId:null});
export const gunDropChance=wave=>.0015+.0005*(Math.max(1,Math.min(10,wave))-1);
export class DualRun extends Run{
 reset(){super.reset();this.dual=true;this.selectedWeapon=0;this.weapons=[fresh(this.lab.gun),fresh(null)];this.guaranteedGunWaves=[];this.guaranteedGunTimes=Object.fromEntries([1,3].map(w=>[w,WAVE_SECONDS[w-1]*(.5+Math.min(.999999,Math.max(0,this.random()))*.35)]));this.pendingGun=null;this.weaponShots=new Set();this.evolutionZones=[];this.targetId=null;this.evolutionShots=0;this.loadWeapon(0)}
 start(gun='normal'){if(gun!=='normal'&&!RECIPES[gun])return false;this.reset();this.lab.gun={type:gun,level:gun==='normal'?0:1,rank:0};this.saveWeapon();this.state='playing';return true}
 saveWeapon(){if(!this.weapons)return;const w=this.weapons[this.selectedWeapon];w.gun=this.lab.gun.empty?null:this.lab.gun;for(const key of fields)w[key]=this[key]}
 loadWeapon(index){this.selectedWeapon=index;const w=this.weapons[index];this.lab.gun=w.gun||{type:'normal',level:0,rank:0,empty:true};for(const key of fields)this[key]=w[key]}
 selectWeapon(index){if(![0,1].includes(index))return false;this.saveWeapon();this.loadWeapon(index);return true}
 withWeapon(index,fn){const previous=this.selectedWeapon;this.selectWeapon(index);try{return fn()}finally{this.selectWeapon(previous)}}
 gunTypes(){this.saveWeapon();return this.weapons.map(w=>w.gun?.type).filter(t=>t&&t!=='normal')}
 randomGun(){const owned=this.gunTypes(),all=Object.keys(RECIPES),others=all.filter(t=>!owned.includes(t));const pool=owned.length<2?others:this.random()<.8?owned:others;return pool[Math.min(pool.length-1,Math.floor(this.random()*pool.length))]}
 pickupGun(type){if(!RECIPES[type])return false;this.saveWeapon();const same=this.weapons.findIndex(w=>w.gun?.type===type);if(same>=0){const w=this.weapons[same];w.gun.rank=Math.min(10,(w.gun.rank||0)+1);this.lastPickup=`${weaponName(w.gun)} +${w.gun.rank}`;this.events.push('gunPickup');this.loadWeapon(this.selectedWeapon);return true}const empty=this.weapons.findIndex(w=>!w.gun||w.gun.type==='normal');if(empty>=0){this.weapons[empty].gun={type,level:1,rank:0};if(this.selectedWeapon===empty)this.loadWeapon(empty);this.events.push('gunPickup');this.lastPickup=`获得${RECIPES[type].name}`;return true}this.pendingGun=type;this.state='gunReward';return true}
 resolveGunPickup(index){if(this.state!=='gunReward'||!this.pendingGun)return false;if(index!==null&&![0,1].includes(index))return false;if(index!==null){this.saveWeapon();const w=this.weapons[index];this.weapons[index]={...fresh({type:this.pendingGun,level:1,rank:0}),attachments:w.attachments,muzzle:w.muzzle};this.loadWeapon(this.selectedWeapon)}this.pendingGun=null;this.state='playing';return true}
 collect(d){if(d.collected)return;if(d.kind==='gun'){if(this.state!=='playing')return;d.collected=true;this.pickupGun(d.gunType);return}if(d.kind==='equipment'){if(this.state!=='playing')return;this.rewardTaken=false;super.collect(d);if(this.state==='reward'&&d.rewardKind==='accessory')this.rewardChoices=this.accessoryOffers();return}super.collect(d)}
 accessoryOffers(){this.saveWeapon();const owned=this.gunTypes(),ids=Object.keys(ACCESSORIES);const matching=ids.filter(id=>owned.includes(ACCESSORIES[id].gun)&&this.weapons.some(w=>w.gun?.type===ACCESSORIES[id].gun&&!w.attachments.includes(id)));const others=ids.filter(id=>!matching.includes(id));for(let i=others.length-1;i>0;i--){const j=Math.floor(this.random()*(i+1));[others[i],others[j]]=[others[j],others[i]]}return [...matching,...others].slice(0,3)}
 chooseReward(id,position=null){if(this.state!=='reward')return false;if(id===null){this.heal(50);this.state='playing';this.rewardChoices=[];return true}if(!this.rewardChoices.includes(id))return false;if(!position||![0,1].includes(position.weapon))return false;const wi=position.weapon,slot=position.slot;if(this.rewardKind==='accessory'&&![0,1].includes(slot))return false;this.saveWeapon();const w=this.weapons[wi];if(this.rewardKind==='accessory'){if(w.attachments.includes(id))return false;w.attachments[slot]=id;w.accessoryCharge={};w.condenser.clear()}else{if(!MUZZLES[id])return false;w.muzzle=id}this.loadWeapon(this.selectedWeapon);this.state='playing';this.rewardChoices=[];return true}
 craft(id,confirm=false){if(this.state!=='lab')return {ok:false,reason:'phase'};this.saveWeapon();if(this.weapons.some((w,i)=>i!==this.selectedWeapon&&w.gun?.type===id))return {ok:false,reason:'other-slot'};const rank=this.lab.gun.type===id?this.lab.gun.rank||0:0,result=super.craft(id,confirm);if(result.ok){this.lab.gun.rank=rank;this.saveWeapon()}return result}
 hit(e,damage,burn=false){const alive=e.hp>0,start=this.drops.length;super.hit(e,damage,burn);if(!alive||e.hp>0)return;if(e.elite){const newDrops=this.drops.slice(start);this.drops.splice(start,newDrops.length,...newDrops.filter(d=>!(d.kind==='equipment'&&d.rewardKind==='accessory')));this.drops.push({kind:'equipment',rewardKind:'accessory',x:e.x,y:e.y,collected:false})}if(this.state==='won'||e.child||e.type===4||e.type===6)return;const guaranteed=[1,3].includes(this.wave)&&!this.guaranteedGunWaves.includes(this.wave)&&this.waveTime>=this.guaranteedGunTimes[this.wave];if(guaranteed||this.random()<gunDropChance(this.wave)){if(guaranteed)this.guaranteedGunWaves.push(this.wave);this.drops.push({kind:'gun',gunType:this.randomGun(),x:e.x+22,y:e.y+12,collected:false,guaranteed})}}
 fireWeapons(dt,bounds){this.saveWeapon();this.weaponShots=new Set();const reserved=new Set(),selected=this.selectedWeapon;let result;
  for(let i=0;i<2;i++){if(!this.weapons[i].gun)continue;this.withWeapon(i,()=>{if(i!==selected)this.shot-=dt;const stats=this.stats,targets=this.enemies.filter(e=>e.hp>0&&visibleInCombat(e,bounds)&&Math.hypot(e.x-this.x,e.y-this.y)<=stats.range).sort((a,b)=>Math.hypot(a.x-this.x,a.y-this.y)-Math.hypot(b.x-this.x,b.y-this.y));let target=targets.find(e=>!reserved.has(e.id))||targets[0];if(target){this.targetId=target.id;reserved.add(target.id)}else this.targetId=null;const bullets=this.bullets.length,effects=this.weaponEffects.length,previousEvents=this.events;this.events=[];this.firePrimary(stats,targets,target,bounds);if(this.events.includes('shot')){this.weaponShots.add(i);afterEvolutionShot(this,bounds)}for(const b of this.bullets.slice(bullets))b.weaponSlot=i;for(const e of this.weaponEffects.slice(effects))e.weaponSlot=i;const ownEvents=this.events;this.events=previousEvents.concat(ownEvents);if(i===selected)result={stats,targets}})}return result||{stats:this.stats,targets:[]}}
 updateGunSystems(dt,previous,stats,targets,bounds){updateAccessoryZones(this,dt,bounds);for(let i=0;i<2;i++){if(!this.weapons[i].gun)continue;this.withWeapon(i,()=>{const events=this.events;this.events=events.filter(e=>e!=='shot');if(this.weaponShots.has(i))this.events.push('shot');const ownTargets=this.enemies.filter(e=>e.hp>0&&visibleInCombat(e,bounds)&&Math.hypot(e.x-this.x,e.y-this.y)<=this.stats.range);this.updateWaterFlow(dt,previous,this.stats,ownTargets.length>0,bounds);updateAccessories(this,dt,bounds,false);this.events=events.concat(this.events.filter(e=>e!=='shot'&&!events.includes(e)))})}updateAccessoryProjectiles(this,dt,bounds);this.saveWeapon()}
 onBulletHit(b,e,bounds){if(b.type==='water')this.withWeapon(b.weaponSlot??0,()=>triggerWaterChain(this,e,bounds));evolutionHit(this,b,e,bounds)}
 onAcidSplash(b,e,bounds){acidSwarm(this,b,e,bounds)}
 advanceEvolutions(dt,bounds){updateEvolutions(this,dt,bounds)}
 canEndWave(){if(![1,3].includes(this.wave)||this.guaranteedGunWaves.includes(this.wave))return true;if(!this.enemies.some(e=>e.hp>0&&!e.child&&e.type!==4&&e.type!==6))this.spawnEnemy(this.wave===1?0:1,this.x<900?Math.min(1100,this.x+240):Math.max(100,this.x-240),Math.max(80,Math.min(720,this.y)));return false}
 endWave(){super.endWave();this.evolutionZones=[];this.saveWeapon();for(let i=0;i<2;i++){const w=this.weapons[i];w.waterParticles=[];w.waterImpacts=[];w.waterMuzzle=null;w.waterEmitting=false;w.condenser.particles=[];w.condenser.impacts=[];w.condenser.muzzle=null}this.loadWeapon(this.selectedWeapon)}
 nextWave(){const result=super.nextWave();if(result){this.saveWeapon();for(const w of this.weapons)w.shot=0;this.loadWeapon(this.selectedWeapon)}return result}
 step(dt,input={}){super.step(dt,input);this.saveWeapon()}
}
